def link_existing_identifiers(apps, schema_editor):
    """existing identifiers are linked to configs (unknown source: all configs,
    except structures which belong to their organization config)
    """
    CrisalidConfig = apps.get_model("crisalid", "CrisalidConfig")
    configs = list(CrisalidConfig.objects.all())
    if not configs:
        return

    StructureIdentifier = apps.get_model("crisalid", "StructureIdentifier")
    through = StructureIdentifier.configs.through
    config_by_organization = {c.organization_id: c.pk for c in configs}
    through.objects.bulk_create(
        [
            through(
                structureidentifier_id=pk,
                crisalidconfig_id=config_by_organization[organization_id],
            )
            for pk, organization_id in StructureIdentifier.objects.values_list(
                "pk", "structure__organization_id"
            )
            if organization_id in config_by_organization
        ],
        ignore_conflicts=True,
    )

    for name in (
        "ResearcherIdentifier",
        "AuthorityOrganizationIdentifier",
        "DocumentIdentifier",
        "JournalIdentifier",
    ):
        model = apps.get_model("crisalid", name)
        through = model.configs.through
        column = f"{name.lower()}_id"
        through.objects.bulk_create(
            [
                through(**{column: pk, "crisalidconfig_id": config.pk})
                for pk in model.objects.values_list("pk", flat=True)
                for config in configs
            ],
            ignore_conflicts=True,
            batch_size=1000,
        )


